    public static void main(String[] args) {
        java.util.Set<String> strings = new java.util.HashSet<>();
        strings.add("hello");
        strings.add("world");
        // This should match and be transformed
        java.lang.StringBuffer buf = new java.lang.StringBuffer(strings.size() * 20);
        for (String s : strings) {
            buf.append(s);
        }
        System.out.println(buf.toString());

        // This should match and be transformed
        java.lang.StringBuffer local = new java.lang.StringBuffer();
        local.append("local var");

        // This StringBuffer is not assigned to a local variable declaration and should NOT match for this rule
        new java.lang.StringBuffer("temp").append("foo");
    }

    // This StringBuffer is a field and should NOT match
    private java.lang.StringBuffer fieldBuffer = new java.lang.StringBuffer("field");
}

